/// <summary>
/// CB521_Exciseregister
/// Report data provider class for Nature 30 and Nature 40 report combine
/// </summary>
[SRSReportParameterAttribute(classStr(METNature3040ReportContract))]
public class METNature3040ReportCombineDP extends SRSReportDataProviderBase
{
    METNature3040ReportsTmp     metNature3040ReportsTmp;
    Query                       reportQuery;       

    #define.Tariff('001')
    #define.LALSUnit('EA')
    #define.LUnit('L')
    #define.LALSUnit30('L of Alcohol')

}

Method.Source:
/// <summary>
/// Method to get the tmp table
/// </summary>
/// <returns>METNature3040ReportsTmp</returns>
[SrsReportDataSet(tableStr(METNature3040ReportsTmp))]
public METNature3040ReportsTmp getMETNature3040ReportsTmp()
{
    select  metNature3040ReportsTmp;
    return  metNature3040ReportsTmp;
}

    /// <summary>
    /// Process method for business logic to insert tmp table
    /// </summary>
    public void processReport()
    {
        METNature3040ReportContract     contract = this.parmDataContract();
        METExciseInformationTable       metExciseInformationTable, metExciseInformationTablePurch;
        METExciseInformationTable       metExciseInformationTableSum;
        METExciseRegisterEntry          metExciseRegisterEntry;
        METTariffItemCodeBase           metTariffItemCodeBase;
        METInventTable                  metInventTable, metInventTableLoc;
        RecordInsertList                recordInsertListTmp = new RecordInsertList(tableNum(METNature3040ReportsTmp), false, false, false, false, false, metNature3040ReportsTmp);
        TransDateTime                   transDateTime = DateTimeUtil::utcNow();

        METExciseRegisterOriginTypes    originTypes;

        Query                           query = new Query(this.buildQuery());

        query.dataSourceTable(tableNum(METExciseInformationTable)).addGroupByAndSelectionField(fieldNum(METExciseInformationTable, ItemId));

        QueryRun                         queryRun = new QueryRun(query);

        while (queryRun.next())
        {
            metExciseInformationTable = queryRun.get(tableNum(METExciseInformationTable));
            metNature3040ReportsTmp.clear();

            metNature3040ReportsTmp.ItemId = metExciseInformationTable.ItemId;
            metNature3040ReportsTmp.ItemDescription = InventTable::find(metExciseInformationTable.ItemId).itemName();

            select firstonly metTariffItemCodeBase
                exists join metInventTable
                    where metTariffItemCodeBase.RecId == metInventTable.METTariffItemCodeBaseRecid  &&
                        metInventTable.ItemId == metExciseInformationTable.ItemId;

            metNature3040ReportsTmp.TariffItem  = metTariffItemCodeBase.TariffItem;
            metNature3040ReportsTmp.TariffItemDescription = metTariffItemCodeBase.Description;
            metNature3040ReportsTmp.StatCode    = metTariffItemCodeBase.StatCode;
            metNature3040ReportsTmp.DutyLAL     = METTariffItemCode::findRecId(metTariffItemCodeBase.RecId).DutyLAL;

            metNature3040ReportsTmp.CasesSold = this.getCasesSold(metExciseInformationTable.ItemId);

            metNature3040ReportsTmp.LALSQuantity = this.getLALSQty(metExciseInformationTable.ItemId, metTariffItemCodeBase, contract.parmMETNat3040(), metNature3040ReportsTmp);
           
            InventQty originalQty;

            if (contract.parmMETNat3040() == METNAT3040::NAT30)
            {
                container tuivAndVFD = this.getTUIVAndVFD(metNature3040ReportsTmp.ItemId);

                metNature3040ReportsTmp.TIUV = conPeek(tuivAndVFD, 1);

                metNature3040ReportsTmp.TariffRate = #Tariff;

                metInventTableLoc =  METInventTable::find(metNature3040ReportsTmp.ItemId);

                metNature3040ReportsTmp.OriginCountryCode   = metInventTableLoc.CountryCode;
                metNature3040ReportsTmp.PreferenceRule      = metInventTableLoc.PreferenceRule;
                metNature3040ReportsTmp.PreferenceScheme    = metInventTableLoc.PreferenceScheme;
                metNature3040ReportsTmp.InvoiceAlcohol      = metInventTableLoc.AlcoholContent;
                metNature3040ReportsTmp.LALSUnit = #LALSUnit;

                metNature3040ReportsTmp.CustomsValue = conPeek(tuivAndVFD, 2); // VFD

                if (metInventTableLoc.beerallowance())
                {
                    metNature3040ReportsTmp.LQuantity = metInventTableLoc.ItemPack * metInventTableLoc.BottleSize * metNature3040ReportsTmp.CasesSold;
                }

                metNature3040ReportsTmp.ExciseAmount = metNature3040ReportsTmp.LALSQuantity * metNature3040ReportsTmp.DutyLAL + (metNature3040ReportsTmp.CustomsValue * metInventTableLoc.metGetAdValoremRate());

                metNature3040ReportsTmp.LUnit = #LUnit;
                originalQty = metNature3040ReportsTmp.LALSQuantity;
            }
            else
            {
                metNature3040ReportsTmp.LALSUnit = #LALSUnit30;
                metNature3040ReportsTmp.LUnit = #LUnit;
                originalQty = metNature3040ReportsTmp.LALSQuantity;
                metNature3040ReportsTmp.ExciseAmount = metNature3040ReportsTmp.LALSQuantity * metNature3040ReportsTmp.DutyLAL;
            }
            
            if (originalQty > 0)
            {
                recordInsertListTmp.add(metNature3040ReportsTmp);
            }
        }

        recordInsertListTmp.insertDatabase();
    }

    /// Consumes available duty credit for a given item and site before reporting the sale quantity in the NAT30/NAT40 report.
    /// Updates the duty credit table by decrementing the credit remaining and marking records as closed when fully used.
    /// </summary>
    /// <param name="_itemId">The item number being processed in the report.</param>
    /// <param name="_siteId">The site associated with the item for duty credit tracking.</param>
    /// <param name="_saleQty">The total quantity of the item to be reported before applying duty credits.</param>
    /// <returns>
    /// The quantity remaining to be reported after applying available duty credits.
    /// If full credit is available, this will return zero; otherwise, returns the uncredited portion.
    /// </returns>
    public static InventQty consumeDutyCredit(ItemId _itemId, InventSiteId _siteId, InventQty _saleQty)
    {
        InventQty remainingQty = _saleQty;
        METDutyCreditTable dutyCreditTable;

        ttsbegin;
    
            while select forupdate dutyCreditTable order by RecId asc
            where dutyCreditTable.ItemId == _itemId &&
              dutyCreditTable.SiteId == _siteId &&
              dutyCreditTable.CreditClosed == NoYes::No
        {
            if (dutyCreditTable.CreditRemaining >= remainingQty)
            {
                dutyCreditTable.CreditRemaining -= remainingQty;

                if (dutyCreditTable.CreditRemaining == 0)
                {
                    dutyCreditTable.CreditClosed = NoYes::Yes;
                }

                dutyCreditTable.update();
                remainingQty = 0;
                break;
            }
            else
            {
                remainingQty -= dutyCreditTable.CreditRemaining;
                dutyCreditTable.CreditRemaining = 0;
                dutyCreditTable.CreditClosed = NoYes::Yes;
                dutyCreditTable.update();
            }
        }

        ttscommit;

        return remainingQty;
    }

    /// <summary>
    /// get TUIV and VFD values per lodgement and sum of all lodgements
    /// </summary>
    /// <param name = "_itemId">itemid</param>
    /// <returns>container tuiv and VFD</returns>
    public container getTUIVAndVFD(ItemId              _itemId)
    {
        METTransportInsurance           TUIVLodgement, TUIV;
        METValueForDuty                 VFDLodgement, VFD;
        METExciseRegisterEntry          metExciseRegisterEntry;
        METExciseInformationTable       metExciseInformationTable;

        InventTable                     inventTableLoc;
        METLodgement                    lodgement;   
        InventQty                       lodgementQty;       
        TransDateTime                   transDateTime = DateTimeUtil::utcNow();
        METExciseRegisterOriginTypes    originTypes;

        Query                           query = new Query(reportQuery);
        QueryBuildDataSource            qbds = query.dataSourceTable(tableNum(METExciseInformationTable));
        qbds.addRange(fieldNum(METExciseInformationTable, ItemId)).value(queryValue(_itemId));

        qbds.addSelectionField(fieldNum(METExciseInformationTable, ItemId));
        qbds.addSelectionField(fieldNum(METExciseInformationTable, Lodgement));
        qbds.addSelectionField(fieldNum(METExciseInformationTable, ReferenceNumber));
        qbds.addSelectionField(fieldNum(METExciseInformationTable, InventoryQty));
        qbds.addSelectionField(fieldNum(METExciseInformationTable, SiteId));
        qbds.addSelectionField(fieldNum(METExciseInformationTable, LodgementAndQtyCon));
        qbds.addSelectionField(fieldNum(METExciseInformationTable, InventTransType));

        QueryRun                        queryRun = new QueryRun(query);
        
        while (queryRun.next())
        {
            metExciseInformationTable = queryRun.get(tableNum(METExciseInformationTable));

            select firstonly RecId from originTypes
                where originTypes.ReferenceId == metExciseInformationTable.InventTransType &&
                      originTypes.UpdateNAT3040 == NoYes::Yes &&
                ((metexciseInformationTable.InventoryQty < 0 && originTypes.TransactionType == METTransactionType::Negative) ||
                 (metexciseInformationTable.InventoryQty > 0 && originTypes.TransactionType == METTransactionType::Positive));

            if (!originTypes.RecId)
            {
                continue;
            }

            List    lodgements = new List(Types::String);
            lodgements = strSplit(metExciseInformationTable.Lodgement, ',');

            ListEnumerator    lodgementEnum = lodgements.getEnumerator();

            while (lodgementEnum.moveNext())
            {
                lodgement = lodgementEnum.current();

                lodgementQty = this.getLodgementQty(metExciseInformationTable, lodgement);
            
                while select validtimestate(transDateTime) metExciseRegisterEntry
                    where metExciseRegisterEntry.ItemId      == metExciseInformationTable.ItemId &&
                          metExciseRegisterEntry.SiteId      == metExciseInformationTable.SiteId &&
                          metExciseRegisterEntry.OrderNumber == metExciseInformationTable.ReferenceNumber &&
                          metExciseRegisterEntry.Lodgement   == lodgement
                {
                    inventTableLoc = InventTable::find(metExciseRegisterEntry.ItemId);

                    InventQty casesSoldLodgement = UnitOfMeasureConverter::convert(lodgementQty,
                        UnitOfMeasure::unitOfMeasureIdBySymbol(inventTableLoc.inventUnitId()),
                        UnitOfMeasure::unitOfMeasureIdBySymbol(this.getSalesOrderUnit(_itemId)),
                        NoYes::Yes,
                        inventTableLoc.Product,
                        NoYes::No);

                    TUIVLodgement = metExciseRegisterEntry.TIUV * casesSoldLodgement;
                    VFDLodgement  = metExciseRegisterEntry.DutyRateReceived * casesSoldLodgement;

                    TUIV = TUIV + TUIVLodgement;
                    VFD  = VFD + VFDLodgement;
                }
            }
        }

        return [TUIV, VFD];
    }

    /// <summary>
    /// Sales unit
    /// </summary>
    /// <param name = "_itemId">itemid</param>
    /// <returns>SalesUnit</returns>
    public METSalesUnit getSalesOrderUnit(ItemId _itemId)
    {
        InventItemSalesSetup inventItemSalesSetup;
        InventDim inventDim;
        InventDim inventDimInventItemSalesSetup;

        select firstonly METSalesUnit from inventItemSalesSetup
            exists join inventDimInventItemSalesSetup
            where inventDimInventItemSalesSetup.inventDimId == inventItemSalesSetup.InventDimId
            && inventItemSalesSetup.ItemId == _itemId
            exists join inventDim
            where inventDim.inventDimId == inventDimInventItemSalesSetup.InventDimId
            && inventDim.InventSiteId == inventDimInventItemSalesSetup.InventSiteId;

        return inventItemSalesSetup.METSalesUnit;
    }

    /// <summary>
    /// get LALS Qty
    /// </summary>
    /// <param name = "_itemId">item</param>
    /// <param name = "_metTariffItemCodeBase">TariffCode</param>
    /// <param name = "_nat3040">nat3040</param>
    /// <param name = "_nature3040ReportsTmp">nature3040</param>
    /// <returns>lals</returns>
    public InventQty getLALSQty(ItemId                      _itemId, 
                                METTariffItemCodeBase       _metTariffItemCodeBase,
                                MetNat3040                  _nat3040,
                                METNature3040ReportsTmp     _nature3040ReportsTmp)
    {
        InventQty                           itemPackQty;
        InventQty                           lalsQty;
        InventQty                           lalqty;
        InventQty                           totalVFD;
        METExciseSiteDutySetup              metExciseSiteDutySetup;
        METTariffItemCode                   metTariffItemCode = METTariffItemCode::findRecId(_metTariffItemCodeBase.recId);
        METInventTable                      metInventTable = METInventTable::find(_itemId);

        itemPackQty = _nature3040ReportsTmp.CasesSold;

        if (metTariffItemCode.BeerAllowance) //Calculation is same for Nat30 and Nat40
        {
            lalsQty = itemPackQty * metInventTable.ItemPack * metInventTable.BottleSize * (metInventTable.AlcoholContent - metInventTable.metGetAdValoremRate());
        }
        else
        {
            lalsQty = itemPackQty * metInventTable.ItemPack * metInventTable.BottleSize * metInventTable.AlcoholContent;
        }
        return abs(lalsQty);
    }

    /// <summary>
    /// Get cases sold
    /// </summary>
    /// <param name = "_itemId">_item id</param>
    /// <returns>InventQty</returns>
    public InventQty getCasesSold(ItemId                      _itemId)
    {
        METExciseInformationTable           metexciseInformationTable;
        METExciseRegisterOriginTypes        originTypes;
        InventQty                           itemPackQtyPerLodgement, itemPackQty;
        InventTable                         inventTable = InventTable::find(_itemId);
        Query                               query = new Query(reportQuery);
        QueryBuildDataSource                qbds = query.dataSourceTable(tableNum(METExciseInformationTable));
        boolean                             validRecord = true;

        qbds.addRange(fieldNum(METExciseInformationTable, ItemId)).value(queryValue(_itemId));

        qbds.addSelectionField(fieldNum(METExciseInformationTable, ItemId));
        qbds.addSelectionField(fieldNum(METExciseInformationTable, SiteId));
        qbds.addSelectionField(fieldNum(METExciseInformationTable, InventoryQty));
        qbds.addSelectionField(fieldNum(METExciseInformationTable, InventTransType));

        QueryRun                            queryRun = new QueryRun(query);

        while (queryRun.next())
        {
            metExciseInformationTable = queryRun.get(tableNum(METExciseInformationTable));

            select firstonly RecId from originTypes
                where originTypes.ReferenceId == metExciseInformationTable.InventTransType &&
                      originTypes.UpdateNAT3040 == NoYes::Yes &&
                ((metexciseInformationTable.InventoryQty < 0 && originTypes.TransactionType == METTransactionType::Negative) ||
                 (metexciseInformationTable.InventoryQty > 0 && originTypes.TransactionType == METTransactionType::Positive));

            if (!originTypes.RecId)
            {
                continue;
            }
            
            itemPackQtyPerLodgement = metexciseInformationTable.InventoryQty;

            if (itemPackQtyPerLodgement < 0)
            {
                itemPackQtyPerLodgement = METNature3040ReportCombineDP::consumeDutyCredit(metexciseInformationTable.ItemId,
                                                                          metexciseInformationTable.SiteId,
                                                                          abs(itemPackQtyPerLodgement));
            }
            else
            {
                itemPackQtyPerLodgement = -1 * itemPackQtyPerLodgement;
            }

            itemPackQty += itemPackQtyPerLodgement;
        }

        itemPackQty = UnitOfMeasureConverter::convert(itemPackQty,
                            UnitOfMeasure::unitOfMeasureIdBySymbol(inventTable.inventUnitId()),
                            UnitOfMeasure::unitOfMeasureIdBySymbol(this.getSalesOrderUnit(_itemId)),
                            NoYes::Yes,
                            inventTable.Product,
                            NoYes::No);
        if (itemPackQty < 0)
        {
            itemPackQty = 0;
        }

        return itemPackQty;
    }

/// <summary>
/// seting global report query variable
/// </summary>
/// <param name = "_reportQuery">query</param>
/// <returns>query</returns>
public Query setReportQuery(Query    _reportQuery)
{
    reportQuery = _reportQuery;
    return reportQuery;
}

    /// <summary>
    /// get data query
    /// </summary>
    /// <returns>query</returns>
    public Query buildQuery()
    {
        METNature3040ReportContract     contract = this.parmDataContract();
        METExciseRegisterOriginTypes    originTypes;
        str                             range;
        QueryBuildRange                 buildRangeTransType, rangeRangeQty;;

        Query                           query = new Query();
        query.addDataSource(tableNum(METExciseInformationTable));

        QueryBuildDataSource            qbds = query.dataSourceTable(tableNum(METExciseInformationTable));
        qbds.name('METExciseInformationTable');

        QueryBuildDataSource            qbdsMetItemTable = qbds.addDataSource(tableNum(METInventTable));
        qbdsMetItemTable.relations(false);
        qbdsMetItemTable.addLink(fieldNum(METExciseInformationTable, ItemId), fieldNum(METInventTable, ItemId));
        qbdsMetItemTable.joinMode(JoinMode::ExistsJoin);

        QueryBuildDataSource            qbdsTariffCode = qbdsMetItemTable.addDataSource(tableNum(METTariffItemCodeBase));
        qbdsTariffCode.relations(false);
        qbdsTariffCode.addLink(fieldNum(METInventTable, METTariffItemCodeBaseRecid), fieldNum(METTariffItemCodeBase, RecId));
        qbdsTariffCode.joinMode(JoinMode::ExistsJoin);

        qbdsTariffCode.addRange(fieldNum(METTariffItemCodeBase, NAT3040)).value(queryValue(contract.parmMETNat3040()));

        if (contract.parmNat30Number())
        {
            qbds.addRange(fieldNum(METExciseInformationTable, Nat3040ReportNumber)).value(queryValue(contract.parmNat30Number()));
        }
        else
        {
            UtcDateTime toDateTime = DateTimeUtil::newDateTime(contract.parmToDate(), 86399);
            utcdatetime fromDateTime = DateTimeUtil::newDateTime(contract.parmFromDate(), 0);
            qbds.addRange(fieldNum(METExciseInformationTable, CreatedDateTime)).value(SysQuery::range(fromDateTime, toDateTime));

            if (contract.parmSite())
            {
                qbds.addRange(fieldNum(METExciseInformationTable, SiteId)).value(SysQuery::value(contract.parmSite()));
            }

            while select originTypes
                where originTypes.UpdateNAT3040 == NoYes::Yes
            {
                qbds.addRange(fieldNum(METExciseInformationTable, InventTransType)).value(queryValue(originTypes.ReferenceId));
            }
        }

        qbds.addRange(fieldNum(METExciseInformationTable, Lodgement)).value(SysQuery::valueNotEmptyString());

        this.setReportQuery(query);

        return query;
    }

    /// <summary>
    /// get lodgement qty
    /// </summary>
    /// <param name = "exciseInformationTable">exciseInfoTable</param>
    /// <param name = "lodgement">lodgment Id</param>
    /// <returns>lodgementQty</returns>
    public InventQty getLodgementQty(METExciseInformationTable  exciseInformationTable, METLodgement  lodgement)
    {

        int i;

        InventQty       lodgementQty;
        container       con = exciseInformationTable.LodgementAndQtyCon;

        i = conFind(con, lodgement);

        lodgementQty = conPeek(con, i + 1);

        if (exciseInformationTable.InventoryQty < 0)
        {
            if (lodgementQty > 0)
            {
                return lodgementQty * -1;
            }
            else
            {
                return lodgementQty;
            }
        }
        else
        {
            if (lodgementQty < 0 )
            {
                return lodgementQty * -1;
            }
            else
            {
                return lodgementQty;
            }
        }
                
    }
